function collapseAnagrams(words: string[]): string[] {
  const key = (w: string) => w.split("").sort().join("");
  const list = words.slice();
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 1; i < list.length; i++) {
      if (key(list[i]) === key(list[i - 1])) { list.splice(i, 1); changed = true; break; }
    }
  }
  return list;
}

