class Solution:
    def collapseAnagrams(self, words: List[str]) -> List[str]:
        lst = list(words)
        changed = True
        while changed:
            changed = False
            for i in range(1, len(lst)):
                if sorted(lst[i]) == sorted(lst[i - 1]):
                    del lst[i]
                    changed = True
                    break
        return lst

