function collapseAnagrams(words: string[]): string[] {
  const key = (w: string) => w.split("").sort().join("");
  const out = [words[0]];
  for (let i = 1; i < words.length; i++) {
    if (key(words[i]) !== key(words[i - 1])) out.push(words[i]);
  }
  return out;
}

